"""
This module handles the creation of commands needed for mirroring the bip trace
on a ASOE testline


The first implementation in this module is following the guideline from the confluence page:
https://confluence.ext.net.nokia.com/pages/viewpage.action?spaceKey=~junewu&title=Capture+light+traffic+mirror+log+without+control+PC

The infromation is retrieved from:
https://confluence.ext.net.nokia.com/display/PSHZ/ASOE+mirror+guide

And from
https://confluence.ext.net.nokia.com/display/~junewu/ASOE+mirroring
"""
from taf.transport.ssh.connection import connect
from taf.collectors.tcpdump.factory import TcpdumpCollectorFactorySelector
from .tools import python_log
from . import bip_config
from contextlib import contextmanager
import logging
import os


RUNNING_COLLECTOR = {}
TARGET_FILE_NAME = "bip_trace_asoe.pcap"
logger = logging.getLogger()


@contextmanager
def connect_to_lmp(gnb_id):
    """
    Context manager for connecting to the lmp of the gnb
    :param gnb_id: The gnb_id of tl config for the gnb to access to
    """
    lmp_connection = bip_config.get_lmp_connection()
    ssh_connection = connect(hostname=lmp_connection['host'],
                             username=lmp_connection['user'],
                             password=lmp_connection['password'])

    yield ssh_connection

    ssh_connection.disconnect()


@python_log
def mirror_log_without_control_pc(gnb_id):
    """
    This function mirrors on the airscale the backplane link to
    the port 13, so the data is streamed to the bsh 1. By this, the
    bip trace can be collected on the bsh 1 later on.
    :param gnb_id: The gnb_id in the testline configuratio for the airscale
    """
    with connect_to_lmp(gnb_id) as lmp_connection:
        # first delete any set mirror rools
        output = lmp_connection.execute('lfs-nw_switch-mirror-tool.sh -L')
        output_lines = [x.strip() for x in output.split('\n') if x.strip()]
        for _ in range(len(output_lines) - 1):
            output = lmp_connection.execute('lfs-nw_switch-mirror-tool.sh -D 1')

        # set mirroring to port 13
        output = lmp_connection.execute('lfs-nw_switch-mirror-tool.sh -S 20000 -f backplane_link -d 13')
        output = lmp_connection.execute('lfs-nw_switch-mirror-tool.sh -S 1010 -f L1_L2_LOKIA_SNF -d 13')
        output = lmp_connection.execute('lfs-nw_switch-mirror-tool.sh -S 10 -f L1_L2_LOKIA_SNF -d 13')
        output = lmp_connection.execute('lfs-nw_switch-mirror-tool.sh -S 1000 -f L1_L2_LOKIA_SNF -d 13')
        output = lmp_connection.execute('lfs-nw_switch-mirror-tool.sh -S 100000 -f L2HI_L2RT -d 13')

        output = lmp_connection.execute('lfs-nw_switch-mirror-tool.sh -L')
        output_lines = [x.strip() for x in output.split('\n') if x.strip()]

        logger.info("lfs-nw_switch-mirror-tools.sh -L")
        for line_no, output_line in enumerate(output_lines):
            logger.info("lfs-nw_switch-mirror-tools.sh output[{}]: {}".format(line_no, output_line))


@python_log
def get_collector_configuration(**kwargs):
    """
    Translates the given arguments to a configuration, which fits to the factory of the
    tcpdump collector
    """
    configuration = {'name': 'bip_trace'}
    for parameter_name, parameter_value in kwargs.items():
        if parameter_name in ["executor", "tcpdump_path", "target_file_name", "sudo_password", "options",
                              "start_timeout", "stop_timeout", "container", "kubectl_exec_options"]:
            if parameter_value is not None:
                configuration[parameter_name] = float(parameter_value)\
                    if parameter_name in ["start_timeout", "stop_timeout"] else parameter_value

    return configuration


@python_log
def start_collector_on_asoe_bsh(gnb_id, target_file_name="target_bip_asoe_trace.pcap"):
    """
    Starts the collection on the baseband module on etha01.212 for bip trace collection.
    """
    global TARGET_FILE_NAME

    TARGET_FILE_NAME = target_file_name

    grep_ipv6 = "bsh 1 ifconfig etha01.212 | grep inet6 | grep -i global | grep -oE '(\\w{1,4}\\:){7}(\\w{1,4})'"
    with connect_to_lmp(gnb_id) as ssh_conn:
        output = ssh_conn.execute(grep_ipv6)
    logger.debug("output of bsh call: {}".format(output))

    bsh_1_ipv6 = output.strip()

    lmp_connection = bip_config.get_lmp_connection(gnb_id)
    parameters = {'host': bsh_1_ipv6,
                  'user': 'toor4nsn',
                  'password': 'oZPS0POrRieRtu',
                  'proxy': {'host': lmp_connection['host'],
                            'user': lmp_connection['user'],
                            'password': lmp_connection['password']}}

    options = '-i etha01'
    config_params = get_collector_configuration(executor=parameters,
                                                options=options,
                                                target_file_name=target_file_name,
                                                capture_locally=True)
    tcpdump = TcpdumpCollectorFactorySelector().create(configuration=config_params, existing_arguments={})
    tcpdump.setup()
    tcpdump.start()
    RUNNING_COLLECTOR[gnb_id] = tcpdump


@python_log
def start(gnb_id=0):
    mirror_log_without_control_pc(gnb_id)
    start_collector_on_asoe_bsh(gnb_id, target_file_name="asoe_bip_trace.pcap")


@python_log
def stop(gnb_id=0):
    if gnb_id in RUNNING_COLLECTOR:
        tcpdump = RUNNING_COLLECTOR[gnb_id]
        tcpdump.stop()
    else:
        logger.error("Stop Collecting Logs on ASOE FAILED! Was not started!")


@python_log
def collect(gnb_id=0, target_dir="/tmp"):
    if gnb_id in RUNNING_COLLECTOR:
        tcpdump = RUNNING_COLLECTOR[gnb_id]
        tcpdump.collect(target_dir=target_dir)
        RUNNING_COLLECTOR.pop(gnb_id)
        return [os.path.join(target_dir, 'bip_trace', TARGET_FILE_NAME)]
    else:
        logger.error("Collecting Logs on ASOE FAILED! Was not started!")
